function validate([rods]) {
  if (!Array.isArray(rods) || rods.length < 1 || rods.length > 20) return 'rods needs 1 to 20 lengths.';
  if (rods.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each rod is a whole number from 1 to 1000.';
  if (rods.reduce((a, b) => a + b, 0) > 5000) return 'The rods add up to at most 5000.';
  return null;
}

