function tallestBillboard(rods) {
  const total = rods.reduce((sum, rod) => sum + rod, 0);
  let dp = new Array(total + 1).fill(-1);
  dp[0] = 0;
  for (const rod of rods) {
    const next = dp.slice();
    for (let diff = 0; diff <= total; diff++) {
      if (dp[diff] < 0) {
        continue;
      }
      const taller = diff + rod;
      next[taller] = Math.max(next[taller], dp[diff]);
      const gap = Math.abs(diff - rod);
      next[gap] = Math.max(next[gap], dp[diff] + Math.min(diff, rod));
    }
    dp = next;
  }
  return dp[0];
}

