function tallestBillboard(rods) {
  // Meet in the middle: try all 3^(n/2) ways to send each rod of a half left, right, or nowhere.
  const collect = (list) => {
    const best = new Map();
    const place = (i, left, right) => {
      if (i === list.length) {
        const key = left - right;
        if (!best.has(key) || best.get(key) < left) best.set(key, left);
        return;
      }
      place(i + 1, left, right);
      place(i + 1, left + list[i], right);
      place(i + 1, left, right + list[i]);
    };
    place(0, 0, 0);
    return best;
  };
  const half = rods.length >> 1;
  const front = collect(rods.slice(0, half));
  const back = collect(rods.slice(half));
  // Halves whose left-minus-right differences cancel give two equal supports.
  let answer = 0;
  for (const [key, left] of front) {
    if (back.has(-key)) answer = Math.max(answer, left + back.get(-key));
  }
  return answer;
}

