function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 16 + pick(5) : 1 + pick(9);
  const caps = large ? [60, 250, 600, 1000] : [3, 8, 20, 1000];
  const cap = caps[pick(caps.length)];
  const rods = Array.from({ length: n }, () => 1 + pick(cap));
  // Shrink random rods until the total fits the limit of 5000.
  let total = rods.reduce((a, b) => a + b, 0);
  while (total > 5000) {
    const i = pick(n);
    const smaller = 1 + Math.floor(rods[i] / 2);
    total -= rods[i] - smaller;
    rods[i] = smaller;
  }
  return [rods];
}
